findPr: function (issueNumber, branchPrefix) {
    var branch = branchPrefix + issueNumber;
    var headFilter = owner + ':' + branch;
    var list = listOpenPrs();
    var open = list.filter(function (p) {
        return (p.head && p.head.label) === headFilter;
    });
