                if (cname.indexOf(BOOKKEEPING_CHECK_PREFIXES[bi]) === 0) { bookkept++; return; }
            }
            if (concl === 'CANCELLED') { ignored++; return; }
            if (concl === 'FAILURE' || concl === 'TIMED_OUT') red = true;
            else if (!concl || status === 'QUEUED' || status === 'IN_PROGRESS' ||
