    resolveMachineAuthor: resolveMachineAuthor,
    machineAuthorLogins: machineAuthorLogins,
    isMachineLogin: isMachineLogin,
    isMachineReleaseBump: isMachineReleaseBump,
    isMachineAuthored: isMachineAuthored
};

